import struct, os
for fn in ['assets/afl-http.pcap','assets/flush_all.pcap']:
    data=open(fn,'rb').read(24)
    print(fn, len(open(fn,'rb').read()), data.hex())
    if len(data)>=24:
        magic=data[:4]
        endian='<' if magic in [b'\xd4\xc3\xb2\xa1', b'M<\xb2\xa1'] else '>'
        print('magic', magic.hex(), 'endian', endian, 'hdr', struct.unpack(endian+'IHHIIII', data))
